class Solution:
    def sellingWood(self, m: int, n: int, prices: List[List[int]]) -> int:
        from functools import lru_cache
        price = {(h, w): p for h, w, p in prices}
        @lru_cache(maxsize=None)
        def solve(i, j):
            if i == 0 or j == 0:
                return 0
            best = price.get((i, j), 0)
            for c in range(1, i // 2 + 1):
                best = max(best, solve(c, j) + solve(i - c, j))
            for c in range(1, j // 2 + 1):
                best = max(best, solve(i, c) + solve(i, j - c))
            return best
        return solve(m, n)

