class Solution {
public:
    vector<vector<long long>> memo;
    vector<vector<long long>> price;
    long long solve(int i, int j) {
        if (i == 0 || j == 0) return 0;
        long long& res = memo[i][j];
        if (res != -1) return res;
        res = price[i][j];
        for (int c = 1; c <= i / 2; c++) res = max(res, solve(c, j) + solve(i - c, j));
        for (int c = 1; c <= j / 2; c++) res = max(res, solve(i, c) + solve(i, j - c));
        return res;
    }
    long long sellingWood(int m, int n, vector<vector<int>>& prices) {
        price.assign(m + 1, vector<long long>(n + 1, 0));
        for (auto& p : prices) price[p[0]][p[1]] = p[2];
        memo.assign(m + 1, vector<long long>(n + 1, -1));
        return solve(m, n);
    }
};

